<?php
$editingAdhkar=($adhkarFormMode ?? '') === 'edit';$adhkarDraft=$adhkarDraft ?? [];
$adhkarRevision=$editingAdhkar ? (int)$adhkarDraft['revision'] : 0;$adhkarConflict=false;
$adhkarHasDraft=$adminError !== '' && (!$editingAdhkar ? ($_POST['kind'] ?? '') === 'adhkar' : ($_POST['content_type'] ?? '') === 'adhkar' && ($_POST['content_action'] ?? '') === 'update' && (int)($_POST['id'] ?? 0) === (int)$adhkarDraft['id']);
if ($adhkarHasDraft) {
    foreach (['title','formula','source_reference','source_url','category','repeat_count','sort_order'] as $field) if (is_string($_POST[$field] ?? null)) $adhkarDraft[$field]=mb_substr($_POST[$field],0,5001,'UTF-8');
    foreach (['reviewed'=>'is_reviewed','publish'=>'is_published'] as $field=>$stored) $adhkarDraft[$stored]=isset($_POST[$field]);
    if ($editingAdhkar) {$submitted=filter_var($_POST['expected_revision'] ?? null,FILTER_VALIDATE_INT);$adhkarConflict=$submitted !== $adhkarRevision;$adhkarRevision=$submitted === false ? 0 : $submitted;}
}
?>
<?php if (!$editingAdhkar): ?><article class="knowledge-card admin-adhkar-create"><h2><?= $editorialCopy('إضافة ذكر مُراجع','Add a reviewed item') ?></h2><?php else: ?>
<div class="inventory-actions"><?php foreach (['toggle'=>['تبديل النشر','Toggle publication'],'delete'=>['حذف','Delete']] as $action=>$label): ?><form method="post" action="/admin#admin-content" <?= $action === 'delete' ? 'data-confirm="'.$editorialCopy('حذف هذا النص من الفهرس؟ يُحتفظ بالتقدم الشخصي.','Delete this catalog item? Personal progress is retained.').'"' : '' ?>><?= csrf_field() ?><input type="hidden" name="kind" value="content"><input type="hidden" name="content_type" value="adhkar"><input type="hidden" name="content_action" value="<?= $action ?>"><input type="hidden" name="id" value="<?= (int)$adhkarDraft['id'] ?>"><input type="hidden" name="expected_revision" value="<?= (int)$row['revision'] ?>"><button class="text-button" <?= $adhkarConflict ? 'disabled' : '' ?>><?= $editorialCopy(...$label) ?></button></form><?php endforeach; ?></div>
<details class="inventory-edit" <?= $adhkarHasDraft ? 'open' : '' ?>><summary><?= $editorialCopy('تعديل التفاصيل','Edit details') ?> · <?= $editorialCopy('النسخة','Version') ?> <?= (int)$row['revision'] ?></summary><?php endif; ?>
<?php if ($adhkarConflict): ?><p class="notice notice-error" data-adhkar-conflict><?= $editorialCopy('احتُفظ بمسودتك دون الكتابة فوق النسخة الأحدث.','Your unsaved draft is retained; the newer version has not been overwritten.') ?> <a href="/admin?content_reload=adhkar-<?= (int)$adhkarDraft['id'] ?>#admin-content"><?= $editorialCopy('تحميل النسخة الحالية','Load current version') ?></a></p><?php endif; ?>
<form class="form-stack" method="post" action="/admin#<?= $editingAdhkar ? 'admin-content' : 'admin-create' ?>" data-adhkar-form>
<?= csrf_field() ?><input type="hidden" name="kind" value="<?= $editingAdhkar ? 'content' : 'adhkar' ?>">
<?php if ($editingAdhkar): ?><input type="hidden" name="content_type" value="adhkar"><input type="hidden" name="content_action" value="update"><input type="hidden" name="id" value="<?= (int)$adhkarDraft['id'] ?>"><input type="hidden" name="expected_revision" value="<?= (int)$adhkarRevision ?>"><?php endif; ?>
<?php foreach (['title'=>['العنوان','Title',200],'source_reference'=>['التوثيق والمرجع','Attribution and source reference',300],'category'=>['التصنيف','Category',80]] as $field=>$label): ?><label><?= $editorialCopy($label[0],$label[1]) ?><input name="<?= $field ?>" minlength="2" maxlength="<?= $label[2] ?>" value="<?= e((string)($adhkarDraft[$field] ?? '')) ?>" required></label><?php endforeach; ?>
<label><?= $editorialCopy('النص','Text') ?><textarea name="formula" minlength="2" maxlength="5000" rows="4" required><?= e((string)($adhkarDraft['formula'] ?? '')) ?></textarea></label>
<label><?= $editorialCopy('رابط المصدر','Source link') ?><input type="url" name="source_url" dir="ltr" maxlength="500" value="<?= e((string)($adhkarDraft['source_url'] ?? '')) ?>" required></label>
<div class="admin-form-grid"><label><?= $editorialCopy('التكرار (اختياري)','Repeat count (optional)') ?><input type="number" name="repeat_count" dir="ltr" min="1" max="1000" value="<?= e((string)($adhkarDraft['repeat_count'] ?? '')) ?>"><small><?= $editorialCopy('الفراغ يعني عدم تحديد عدد ثابت؛ لا يُفترض عدد بديل.','Blank means no fixed count; no replacement count is assumed.') ?></small></label><label><?= $editorialCopy('ترتيب العرض','Order') ?><input type="number" name="sort_order" dir="ltr" min="-100000" max="100000" value="<?= e((string)($adhkarDraft['sort_order'] ?? 0)) ?>" required></label></div>
<label class="check-label"><input type="checkbox" name="reviewed" required <?= !empty($adhkarDraft['is_reviewed']) ? 'checked' : '' ?>><?= $editorialCopy('تمت المراجعة التحريرية والتوثيق','Editorial review and attribution confirmed') ?></label>
<label class="check-label"><input type="checkbox" name="publish" <?= !empty($adhkarDraft['is_published']) ? 'checked' : '' ?>><?= $editorialCopy('نشر','Publish') ?></label>
<button class="button button-primary" <?= $adhkarConflict ? 'disabled' : '' ?>><?= $editorialCopy('حفظ الذكر','Save item') ?></button></form><?php if ($editingAdhkar): ?></details><?php else: ?></article><?php endif; ?>
